/* features: 33 float; out_probabilities: 2 float veya NULL.
   Dönüş: en olası sınıfın indeksi. */
static int human_detector_predict(const float* features, float* out_probabilities) {
    float votes[2] = {0};
    human_detector_tree_0(features, votes);
    human_detector_tree_1(features, votes);
    human_detector_tree_2(features, votes);
    human_detector_tree_3(features, votes);
    human_detector_tree_4(features, votes);
    human_detector_tree_5(features, votes);
    human_detector_tree_6(features, votes);
    human_detector_tree_7(features, votes);
    human_detector_tree_8(features, votes);
    human_detector_tree_9(features, votes);
    human_detector_tree_10(features, votes);
    human_detector_tree_11(features, votes);
    human_detector_tree_12(features, votes);
    human_detector_tree_13(features, votes);
    human_detector_tree_14(features, votes);
    human_detector_tree_15(features, votes);
    human_detector_tree_16(features, votes);
    human_detector_tree_17(features, votes);
    human_detector_tree_18(features, votes);
    human_detector_tree_19(features, votes);
    human_detector_tree_20(features, votes);
    human_detector_tree_21(features, votes);
    human_detector_tree_22(features, votes);
    human_detector_tree_23(features, votes);
    human_detector_tree_24(features, votes);

    int best_class = 0;
    float max_prob = -1.0f;
    for (int c = 0; c < 2; c++) {
        float p = votes[c] / (float)25;
        if (out_probabilities) out_probabilities[c] = p;
        if (p > max_prob) {
            max_prob = p;
            best_class = c;
        }
    }
    return best_class;
}

